buggy.reported_examples:
import pandas as pd
import numpy as np
from pandas import Timedelta
from pandas._libs.tslibs import OutOfBoundsTimedelta

# Example 1: Timedelta.min + np.array([-1], 'm8[ns]')
try:
    result = Timedelta.min + np.array([-1], 'm8[ns]')
    probe("Timedelta.min + np.array([-1], 'm8[ns]')", result)
except OutOfBoundsTimedelta as e:
    probe("Timedelta.min + np.array([-1], 'm8[ns]')", f"__error__: OutOfBoundsTimedelta: {str(e)}")
except Exception as e:
    probe("Timedelta.min + np.array([-1], 'm8[ns]')", f"__error__: {type(e).__name__}: {str(e)}")

# Example 2: Timedelta.min + np.array([-2], 'm8[ns]')
try:
    result = Timedelta.min + np.array([-2], 'm8[ns]')
    probe("Timedelta.min + np.array([-2], 'm8[ns]')", result)
except OutOfBoundsTimedelta as e:
    probe("Timedelta.min + np.array([-2], 'm8[ns]')", f"__error__: OutOfBoundsTimedelta: {str(e)}")
except Exception as e:
    probe("Timedelta.min + np.array([-2], 'm8[ns]')", f"__error__: {type(e).__name__}: {str(e)}")

# Example 3: Timedelta(10**12, 's') + np.array([1], 'm8[ns]')
try:
    result = Timedelta(10**12, 's') + np.array([1], 'm8[ns]')
    probe("Timedelta(10**12, 's') + np.array([1], 'm8[ns]')", result)
except OutOfBoundsTimedelta as e:
